package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.NullValueProvider;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.NullValueProvider.NullValue;
import com.fasterxml.jackson.databind.deser.std.NullValueProvider;
import com.fasterxml.jackson.databind.introspect.AnnotatedWithParams;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class StringCollectionDeserializer_deserialize_TriageGen1Test {

    @Mock
    private JsonParser p;

    @Mock
    private DeserializationContext ctxt;

    @Mock
    private JavaType collectionType;

    @Mock
    private com.fasterxml.jackson.databind.JsonDeserializer<?> valueDeser;

    @Mock
    private NullValueProvider nullProvider;

    private StringCollectionDeserializer deserializer;
    private Collection<String> result;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        result = new ArrayList<>();
        // We use a spy or a subclass to inject the nullProvider since it's likely a private field 
        // or set via withResolved. For testing purposes, we'll assume we can manipulate the state.
        deserializer = new StringCollectionDeserializer(collectionType, null, null);

        // Use reflection or a protected method if available to inject nullProvider for the test
        try {
            java.lang.reflect.Field field = StringCollectionDeserializer.class.getDeclaredField("_nullProvider");
            field.setAccessible(true);
            field.set(deserializer, nullProvider);
        } catch (Exception e) {
            // Fallback if field name/access differs in specific Jackson versions
        }
    }

    @Test
    public void testDeserialize_NotStartArray_CallsHandleNonArray() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(false);

        // Since handleNonArray is protected and likely returns the result or throws, 
        // we test the branch. We wrap in a spy to verify the call or check the behavior.
        StringCollectionDeserializer spyDeserializer = spy(deserializer);

        spyDeserializer.deserialize(p, ctxt, result);

        verify(spyDeserializer).handleNonArray(p, ctxt, result);
    }

    @Test
    public void testDeserialize_WithCustomValueDeserializer() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);

        // Re-instantiate with a value deserializer
        deserializer = new StringCollectionDeserializer(collectionType, valueDeser, null);

        deserializer.deserialize(p, ctxt, result);

        // Verify that deserializeUsingCustom is called (indirectly by checking valueDeser interaction)
        // Note: deserializeUsingCustom is a protected method in the base class.
        verify(p, atLeastOnce()).getCurrentToken(); 
    }

    @Test
    public void testDeserialize_Success_WithTextValues() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextTextValue()).thenReturn("a", "b", null);
        when(p.getCurrentToken()).thenReturn(JsonToken.END_ARRAY);

        deserializer.deserialize(p, ctxt, result);

        assertEquals(2, result.size());
        assertEquals("a", result.get(0));
        assertEquals("b", result.get(1));
    }

    @Test
    public void testDeserialize_Success_WithNullValues_SkipNullTrue() throws IOException {
        // We need to set _skipNullValues to true. 
        // This usually requires using the 'withResolved' method or reflection.
        deserializer = new StringCollectionDeserializer(collectionType, null, null)
                .withResolved(null, null, nullProvider, false);

        // Manually set skipNullValues via reflection for coverage
        try {
            java.lang.reflect.Field field = StringCollectionDeserializer.class.getDeclaredField("_skipNullValues");
            field.setAccessible(true);
            field.set(deserializer, true);
        } catch (Exception e) {}

        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextTextValue()).thenReturn("val", null);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_NULL);
        // After VALUE_NULL, it should loop again. We simulate it hitting END_ARRAY next.
        when(p.nextTextValue()).thenReturn(null); 
        // We need to handle the loop carefully to avoid infinite loop in test
        // Mocking p.nextTextValue() to return null, then p.getCurrentToken() to return END_ARRAY
        reset(p);
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextTextValue()).thenReturn("val", null);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_NULL, JsonToken.END_ARRAY);

        deserializer.deserialize(p, ctxt, result);

        assertEquals(1, result.size());
        assertEquals("val", result.get(0));
    }

    @Test
    public void testDeserialize_Success_WithNullValues_SkipNullFalse() throws IOException {
        deserializer = new StringCollectionDeserializer(collectionType, null, null)
                .withResolved(null, null, nullProvider, false);

        try {
            java.lang.reflect.Field field = StringCollectionDeserializer.class.getDeclaredField("_skipNullValues");
            field.setAccessible(true);
            field.set(deserializer, false);
        } catch (Exception e) {}

        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextTextValue()).thenReturn("val", null);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_NULL, JsonToken.END_ARRAY);
        when(nullProvider.getNullValue(ctxt)).thenReturn("null_str");

        deserializer.deserialize(p, ctxt, result);

        assertEquals(2, result.size());
        assertEquals("val", result.get(0));
        assertEquals("null_str", result.get(1));
    }

    @Test
    public void testDeserialize_Success_WithComplexStrings() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextTextValue()).thenReturn(null); // Trigger _parseString
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_STRING);
        // We need to mock the protected _parseString behavior. 
        // Since we can't easily mock protected methods of the class under test directly without spy,
        // we rely on the fact that we are testing the branch.

        StringCollectionDeserializer spyDeserializer = spy(deserializer);
        doReturn("parsed_val").when(spyDeserializer)._parseString(p, ctxt);

        // To prevent infinite loop in while(true), make it return null then END_ARRAY
        when(p.nextTextValue()).thenReturn(null);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_STRING, JsonToken.END_ARRAY);

        spyDeserializer.deserialize(p, ctxt, result);

        assertEquals(1, result.size());
        assertEquals("parsed_val", result.get(0));
    }

    @Test(expected = JsonMappingException.class)
    public void testDeserialize_ThrowsException_WrapsWithMappingException() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextTextValue()).thenThrow(new RuntimeException("Unexpected error"));

        deserializer.deserialize(p, ctxt, result);
    }
}
